-- Seed: Indicadores de 6to de Secundaria - Ciencias Sociales

INSERT INTO public.curr_indicadores (grado, asignatura, competencia, codigo, descripcion) VALUES
-- BC1
('6to', 'Ciencias Sociales', 'BC1', 'IL-1', 'Identifica información relacionada con diferentes aspectos geográficos y ecológicos del territorio dominicano, como cuencas hidrográficas, áreas protegidas, variantes climáticas, zonas ecológicas, ecosistemas costeros y marinos, a través de mapas y otras fuentes confiables.'),
('6to', 'Ciencias Sociales', 'BC1', 'IL-2', 'Utiliza fuentes de información confiables sobre el crecimiento demográfico en la República Dominicana, los cambios en la tasa de natalidad y mortalidad.'),
('6to', 'Ciencias Sociales', 'BC1', 'IL-3', 'Compara estudios económicos sobre el Producto Nacional Bruto, así como el Producto Interior Neto, y evalúa su impacto en el equilibrio monetario del Estado.'),

-- BC2
('6to', 'Ciencias Sociales', 'BC2', 'IL-4', 'Elabora una línea de tiempo que muestre los acontecimientos más relevantes que han ocurrido en la República Dominicana desde 1916 hasta la actualidad.'),
('6to', 'Ciencias Sociales', 'BC2', 'IL-5', 'Compara de forma crítica textos de historiadores sobre diferentes períodos de la historia dominicana, como la dictadura de Trujillo, el gobierno de Juan Bosch, el triunvirato y la Revolución de Abril, en términos de sus sistemas sociales, políticos y económicos.'),
('6to', 'Ciencias Sociales', 'BC2', 'IL-6', 'Analiza mapas e informaciones históricas sobre los acontecimientos relevantes ocurridos durante la primera ocupación estadounidense de 1916 a 1924, al igual que los cambios y sucesos que se dieron desde 1924 hasta 1930.'),
('6to', 'Ciencias Sociales', 'BC2', 'IL-7', 'Analiza gráficos y datos estadísticos sobre la ley de oferta y demanda en la economía dominicana durante los períodos históricos estudiados.'),
('6to', 'Ciencias Sociales', 'BC2', 'IL-8', 'Analiza información de fuentes confiables, la relación entre el Golpe de Estado a Juan Bosch, el Triunvirato y la Revolución de Abril, y su impacto en los 12 años de gobierno de Joaquín Balaguer.'),
('6to', 'Ciencias Sociales', 'BC2', 'IL-9', 'Comprende las implicaciones de la ley de oferta y demanda en la economía de la República Dominicana.'),

-- BC3
('6to', 'Ciencias Sociales', 'BC3', 'IL-13', 'Analiza, a través de ensayos y monografías, las implicaciones del crecimiento poblacional y económico, así como sus variantes de desarrollo y subdesarrollo desde 1950 hasta la actualidad.'),
('6to', 'Ciencias Sociales', 'BC3', 'IL-14', 'Utiliza información obtenida de diversas fuentes de estudios sociales, políticos y económicos para analizar la evolución de la República Dominicana desde 1961 hasta la actualidad.'),
('6to', 'Ciencias Sociales', 'BC3', 'IL-15', 'Aplica las fórmulas de tasa de natalidad y mortalidad al estudiar el crecimiento y decrecimiento poblacional.'),
('6to', 'Ciencias Sociales', 'BC3', 'IL-16', 'Elabora proyectos planteando soluciones a situaciones mundiales que propician el deterioro ambiental y el cambio climático.'),
('6to', 'Ciencias Sociales', 'BC3', 'IL-17', 'Argumenta sobre los problemas globales de acceso al agua, incluyendo la deforestación, sequías, distribución desigual, sistemas de acopio y riego, contaminación, sobreexplotación y desperdicio.'),
('6to', 'Ciencias Sociales', 'BC3', 'IL-18', 'Expone argumentos sobre los desafíos globales relacionados con el acceso al agua, como la deforestación, las sequías, la distribución desigual, la gestión de sistemas de acopio y riego, la contaminación, la sobreexplotación y el desperpendicio.'),

-- BC4
('6to', 'Ciencias Sociales', 'BC4', 'IL-10', 'Realiza comparación entre el proyecto constitucional de Duarte y los de los sectores liberales y conservadores del periodo histórico estudiado.'),
('6to', 'Ciencias Sociales', 'BC4', 'IL-11', 'Diseña y ejecuta campañas escolares y comunitarias que promuevan la educación vial, la defensa de los derechos humanos, el respeto a las leyes constitucionales y los símbolos patrios, empleando estrategias de comunicación efectiva y participación activa de la comunidad.'),
('6to', 'Ciencias Sociales', 'BC4', 'IL-12', 'Elabora resúmenes, informes de lecturas de fuentes de información confiables sobre la identidad dominicana desde el siglo XIX hasta la actualidad y su vinculación con los proyectos de nación que la establecieron.'),
('6to', 'Ciencias Sociales', 'BC4', 'IL-19', 'Examina análisis de los proyectos estatales democráticos y conservadores del siglo XIX, su impacto en la sociedad y economía de la República Dominicana.'),
('6to', 'Ciencias Sociales', 'BC4', 'IL-20', 'Aplica técnicas de análisis crítico en situaciones de diálogo constructivo y negociación colaborativa para resolver conflictos y alcanzar acuerdos mutuos, demostrando habilidades de comunicación efectiva y resolución de conflictos en un contexto laboral o académico.'),
('6to', 'Ciencias Sociales', 'BC4', 'IL-21', 'Sintetiza datos de encuestas y estudios que permiten proponer soluciones al problema migratorio.');
